window.__rgjG=null; window.__rgjErr=null;
(async () => { try {
  const relay = (req) => new Promise(res => {
    const id = 'p' + Math.random().toString(36).slice(2);
    const t = setTimeout(() => { window.removeEventListener('message', h); res({ ok:false, status:0, text:'relay timeout' }); }, 7000);
    function h(ev) { const d = ev.data; if (!d || d.__rgjLan !== 1 || d.id !== id || !d.res) return;
      clearTimeout(t); window.removeEventListener('message', h); res(d.res); }
    window.addEventListener('message', h);
    window.postMessage({ __rgjLan: 1, id, req }, location.origin);
  });
  const base = 'http://192.168.1.169';
  const out = { steps: [] };
  const note = (l, r) => out.steps.push([l, r.status, String(r.text).slice(0,120)]);
  const login = await relay({ method:'POST', url: base + '/api/login', headers:{'Content-Type':'application/json'},
                              body: JSON.stringify({ username:'ark', password:'ark' }) });
  const H = { 'X-Auth': String(login.text||'').replace(/^"|"$/g,'').trim() };
  note('login', login);
  // 1. clear the stray file my earlier POST left behind, then create the real directory
  note('del-rgj', await relay({ method:'DELETE', url: base + '/api/resources/rgj?override=true', headers: H }));
  note('mkdir-rgj', await relay({ method:'POST', url: base + '/api/resources/rgj/?override=false', headers: H, body: '' }));
  note('mkdir-test', await relay({ method:'POST', url: base + '/api/resources/rgjtest-dir/?override=false', headers: H, body: '' }));
  const ls = await relay({ method:'GET', url: base + '/api/resources/?override=true', headers: H });
  try { out.entries = JSON.parse(ls.text).items.filter(i=>/^rgj/.test(i.name)).map(i=>[i.name, i.isDir, i.size]); } catch(e) { out.entries = String(ls.text).slice(0,120); }
  // 2. write the marker inside it and read it straight back
  const marker = JSON.stringify({ schema:1, device_id:'g350_hw01', model:'Batlexp G350', backend:'File Browser', queue:'rgj/rgj-queue.jsonl', written_at:new Date().toISOString() });
  note('write-marker', await relay({ method:'POST', url: base + '/api/resources/rgj/rgj-device.json?override=true',
      headers: { ...H, 'Content-Type':'application/octet-stream' }, body: marker }));
  note('read-marker', await relay({ method:'GET', url: base + '/api/raw/rgj/rgj-device.json', headers: H }));
  window.__rgjG = JSON.stringify(out);
} catch(e) { window.__rgjErr = String(e && e.stack || e); } })();
